use anyhow::{Result,ensure};
use sarv_quote::{domain::State,procurement::*,store::Store};
use serde_json::{Value,json};
use std::{fs,path::{Path,PathBuf},process::{Command,Stdio},sync::{Arc,Barrier},time::{Duration,Instant}};
fn row(profile:&Path)->Result<(i64,String)> {let db=rusqlite::Connection::open(profile.join("sarv.sqlite3"))?;Ok(db.query_row("SELECT generation,payload FROM state WHERE id=1",[],|r|Ok((r.get(0)?,r.get(1)?)))?)}
fn c(state:&State,source:&str,key:&str)->Value {let o=&state.accounting.core.openings[0].command;json!({"company_id":o.company_id,"period_id":o.period_id,"setup_id":o.setup_id,"date":"2026-04-01","source_id":source,"source_revision":1,"request_key":key,"actor":"Independent financial fault reviewer","reason":"Original R-B three-piece45IRR supplier credit after M5 baseline"})}
fn setup(state:&State,path:&Path)->Result<ProcurementCommand>{
 let mut st=Store::open(path)?;st.change(|s|{*s=state.clone();Ok(())})?;
 Ok(serde_json::from_value(json!({"Return":{"context":c(state,"fault-financial-return","fault-financial-key"),"supplier_id":"party-a","return_id":"fault-return","return_reference":"FAULT-RETURN","credit_id":"fault-credit","credit_reference":"FAULT-CREDIT","document_date":"2026-04-01","lines":[{"id":"fault-return-line","receipt_line_id":"receipt105-line","bill_line_id":"bill150-line-1","quantity_thousandths":3000,"supplied_value":45}],"supplied_total":45}}))?)
}
fn check(st:&Store)->Result<()> {
 st.state.validate()?;let a=&st.state.accounting;let company=&a.companies[0].id;
 let r=a.sales_reconcile(company,"2026-04-01")?;let p=a.procurement_reconcile(company,"2026-04-01")?;
 ensure!(a.journals.len()==10&&a.procurement.records.len()==7&&a.sales.records.len()==5&&r.reconciled&&r.cogs.rials()==58&&r.profit.rials()==41&&r.receivables.iter().map(|r|r.remaining.rials()).sum::<i64>()==299&&r.stock.iter().map(|r|r.value.rials()).sum::<i64>()==377&&p.payables.iter().map(|r|r.remaining.rials()).sum::<i64>()==284&&p.total_debit.rials()==1585&&p.total_credit.rials()==1585,"complete supplier credit literal Inv377 AR299 AP284 COGS58 profit41 TB1585 once");
 let returned=a.procurement.records.iter().filter(|r|matches!(r.data,ProcurementData::Return(_))).collect::<Vec<_>>();ensure!(returned.len()==1,"one paired supplier event");
 if let ProcurementData::Return(pair)=&returned[0].data{ensure!(pair.return_id=="fault-return"&&pair.credit_id.as_deref()==Some("fault-credit")&&pair.credit_state.is_some(),"distinct paired IDs/state after fault");}
 let db=rusqlite::Connection::open(st.directory.join("sarv.sqlite3"))?;ensure!(db.query_row("PRAGMA integrity_check",[],|r|r.get::<_,String>(0))?=="ok","database integrity after financial fault");Ok(())
}
fn restore_check(st:&Store)->Result<()> {let backup=st.directory.join("final-financial-backup.json");st.backup(&backup)?;let mut fresh=Store::open(&st.directory.join("fresh-restore"))?;fresh.restore(Store::restore_preview(&backup)?)?;ensure!(serde_json::to_value(&fresh.state)?==serde_json::to_value(&st.state)?,"full financial State fresh restore exact including movements/journals/aliases/quotes");check(&fresh)?;fs::write(st.directory.join("final-state.json"),serde_json::to_vec_pretty(&st.state)?)?;Ok(())}
fn main()->Result<()> {
 let args=std::env::args().collect::<Vec<_>>();
 if args.get(1).map(String::as_str)==Some("--child") {let path=PathBuf::from(&args[2]);let command:ProcurementCommand=serde_json::from_slice(&fs::read(path.join("financial-command.json"))?)?;let st=Store::open(&path)?;let(g,mut candidate)=st.snapshot()?;candidate.accounting.post_procurement_command(command)?;let prepared=Store::prepare_candidate(g,candidate)?;if args[3]=="committed"{Store::commit_detached(path.clone(),prepared)?;}fs::write(path.join("phase-ready"),&args[3])?;loop{std::thread::park();}}
 let state:State=serde_json::from_slice(&fs::read(&args[1])?)?;let out=PathBuf::from(&args[2]);fs::create_dir_all(&out)?;let mut observations=vec![];
 for phase in ["prepared","committed"] {let path=out.join(phase);let command=setup(&state,&path)?;fs::write(path.join("financial-command.json"),serde_json::to_vec_pretty(&command)?)?;let before=row(&path)?;let mut child=Command::new(std::env::current_exe()?).arg("--child").arg(&path).arg(phase).stdout(Stdio::null()).stderr(Stdio::null()).spawn()?;let start=Instant::now();while !path.join("phase-ready").exists(){ensure!(start.elapsed()<Duration::from_secs(15)&&child.try_wait()?.is_none(),"owned financial child reaches explicit phase");std::thread::sleep(Duration::from_millis(10));}child.kill()?;ensure!(!child.wait()?.success(),"owned child killed");let after=row(&path)?;if phase=="prepared"{ensure!(after==before,"before transaction no partial financial event");}else{ensure!(after.0==before.0+1,"durable generation committed before lost receipt");}
  let mut st=Store::open(&path)?;let mut alias=serde_json::to_value(&command)?;alias["Return"]["context"]["request_key"]=format!("retry-after-{phase}").into();let r=st.change(|s|s.accounting.post_procurement_command(serde_json::from_value(alias)?))?;ensure!(r.journal_id.is_some(),"financial retry result");let g=st.local_generation();let before_retry=serde_json::to_value(&st.state)?;let mut key=serde_json::to_value(&command)?;key["Return"]["context"]["request_key"]=format!("retry-after-{phase}").into();st.change(|s|s.accounting.post_procurement_command(serde_json::from_value(key)?))?;ensure!(st.local_generation()==g&&serde_json::to_value(&st.state)?==before_retry,"identical financial retry exact no-op");check(&st)?;restore_check(&st)?;observations.push(json!({"phase":phase,"old_or_complete":true,"final_one_financial_effect":true,"full_state_fresh_restore_exact":true,"software_SIGKILL_only":true,"hardware_power_loss":false}));
 }
 for different_key in [false,true] {let path=out.join(if different_key{"race-different-keys"}else{"race-identical-keys"});let command=setup(&state,&path)?;let st=Store::open(&path)?;let(g,before)=st.snapshot()?;let barrier=Arc::new(Barrier::new(3));let mut workers=vec![];for n in 0..2 {let mut candidate=before.clone();let mut value=serde_json::to_value(&command)?;if different_key{value["Return"]["context"]["request_key"]=format!("financial-race-{n}").into();}candidate.accounting.post_procurement_command(serde_json::from_value(value)?)?;let prepared=Store::prepare_candidate(g,candidate)?;let path=path.clone();let barrier=barrier.clone();workers.push(std::thread::spawn(move||{barrier.wait();Store::commit_detached(path,prepared)}));}barrier.wait();let mut success=0;let mut failure=0;for worker in workers {if worker.join().unwrap().is_ok(){success+=1}else{failure+=1}}ensure!(success==1&&failure==1,"CAS permits one financial writer");let mut st=Store::open(&path)?;ensure!(st.local_generation()==g+1,"single race generation");check(&st)?;let journals=st.state.accounting.journals.clone();let records=st.state.accounting.procurement.records.clone();let audit=st.state.accounting.audit.clone();let mut alias=serde_json::to_value(&command)?;alias["Return"]["context"]["request_key"]="financial-race-reopened-alias".into();st.change(|s|s.accounting.post_procurement_command(serde_json::from_value(alias)?))?;ensure!(st.state.accounting.journals==journals&&st.state.accounting.procurement.records==records&&st.state.accounting.audit==audit,"fresh financial alias after contention does not duplicate effects");check(&st)?;restore_check(&st)?;observations.push(json!({"same_key":!different_key,"simultaneous_detached_writers":2,"success":success,"CAS_rejection":failure,"reopened_fresh_key_alias_same_effect":true,"full_state_fresh_restore_exact":true}));}
 fs::write(out.join("financial-store-observations.json"),serde_json::to_vec_pretty(&observations)?)?;println!("PASS independent paired supplier return-credit SIGKILL before/after durable commit, identical/different-key simultaneous CAS, exact one effect and reopened aliases; Inv377 AR299 AP284 COGS58 profit41 TB1585.");Ok(())
}
